// Writes supabase/seed.sql from the TypeScript seed data, so a fresh Supabase
// project gets exactly the same archive as local development mode.
//
//   npm run db:seed-sql

import { writeFileSync } from "node:fs";
import path from "node:path";
import { buildSeedTables } from "../data/seed";
import { TABLE_ORDER } from "../lib/archive/types";

const tables = buildSeedTables();
const lines: string[] = [
  "-- Generated by `npm run db:seed-sql` from data/seed — edit the TypeScript seed, not this file.",
  "-- Established productions are Confirmed; the sample catalogue is Proposed.",
  "",
  "begin;",
  "",
];

for (const table of TABLE_ORDER) {
  const rows = tables[table];
  if (!rows.length) continue;
  const json = JSON.stringify(rows);
  if (json.includes("$seed$")) throw new Error(`Seed data for ${table} contains the dollar-quote tag.`);
  lines.push(`-- ${table}: ${rows.length} row${rows.length === 1 ? "" : "s"}`);
  lines.push(
    `insert into public.${table} select * from jsonb_populate_recordset(null::public.${table}, $seed$${json}$seed$::jsonb) on conflict (id) do nothing;`,
  );
  lines.push("");
}
lines.push("commit;", "");

const out = path.join(process.cwd(), "supabase", "seed.sql");
writeFileSync(out, lines.join("\n"), "utf8");
console.log(`Wrote ${out} (${tables.productions.length} productions, ${tables.people.length} people, ${tables.studios.length} studios).`);
